def lateral(seg):
    return [f for f in seg.faces() if f.geom_type == GeomType.CYLINDER]
def planar_at(seg, z):
    return [f for f in seg.faces() if f.geom_type == GeomType.PLANE and abs(f.center().Z - z) < 1e-9]

